import { readdirSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { sql } from 'drizzle-orm';
import type { DB } from './client';

/**
 * Tiny driver-agnostic migrator: applies ./drizzle/*.sql (generated by
 * drizzle-kit) in order, once each, recorded in _migrations. Statements are
 * split on drizzle's `--> statement-breakpoint` marker.
 */
export async function migrate(db: DB, dir = process.env.MIGRATIONS_DIR ?? resolve(process.cwd(), 'drizzle')) {
  await db.execute(sql`create table if not exists _migrations (name text primary key, applied_at timestamptz not null default now())`);
  const rows = (await db.execute(sql`select name from _migrations`)) as unknown as { rows?: { name: string }[] } | { name: string }[];
  const list = Array.isArray(rows) ? rows : rows.rows ?? [];
  const done = new Set(list.map((r) => r.name));
  let files: string[] = [];
  try { files = readdirSync(dir).filter((f) => f.endsWith('.sql')).sort(); } catch { return; }
  for (const f of files) {
    if (done.has(f)) continue;
    const text = readFileSync(join(dir, f), 'utf8');
    const stmts = text.split('--> statement-breakpoint').map((s) => s.trim()).filter(Boolean);
    await db.transaction(async (tx) => {
      for (const s of stmts) await tx.execute(sql.raw(s));
      await tx.execute(sql`insert into _migrations (name) values (${f})`);
    });
  }
}
